<div class="wrap mao-tk-toolkit" id="mao-tk-toolkit">
    <h1 class="screen-reader-text"><?php esc_html_e('文章 UI 组件', 'mao-tk-zibll-toolkit'); ?></h1>
    <header class="mao-tk-toolkit__header"><div><div class="mao-tk-toolkit__title-line"><h2><?php esc_html_e('文章 UI 组件', 'mao-tk-zibll-toolkit'); ?></h2><span class="mao-tk-toolkit__version">v<?php echo esc_html(MAO_TK_ZIBLL_TOOLKIT_VERSION); ?></span></div><p class="mao-tk-toolkit__intro"><?php esc_html_e('已确认的文章组件与阅读折叠独立启停，仅作用于明确包装的文章正文。关闭后保留正文和原生功能。', 'mao-tk-zibll-toolkit'); ?></p></div></header>
    <?php $switch_notice = $notice; require MAO_TK_ZIBLL_TOOLKIT_DIR . 'inc/views/switch-feedback.php'; ?>
    <?php if (!class_exists('WP_HTML_Tag_Processor')) : ?><p class="mao-tk-toolkit__message" role="alert"><?php esc_html_e('文章 UI 组件需要 WordPress 6.2 或更新版本的 HTML API，当前增强暂停；原有模块不受影响。', 'mao-tk-zibll-toolkit'); ?></p><?php endif; ?>
    <?php if (!$valid) : ?><p class="mao-tk-toolkit__message" role="alert"><?php esc_html_e('模块配置格式异常，开关写入暂停，原有配置未覆盖。', 'mao-tk-zibll-toolkit'); ?></p><?php endif; ?>
    <div class="mao-tk-toolkit__layout"><div class="mao-tk-toolkit__main"><section class="mao-tk-toolkit__panel">
        <div class="mao-tk-toolkit__section-head"><div><h2><?php esc_html_e('文章组件', 'mao-tk-zibll-toolkit'); ?></h2><p><?php esc_html_e('推荐与工具入口 v1.1.1 已接入；未设置的组件默认启用，已关闭的设置保持。', 'mao-tk-zibll-toolkit'); ?></p></div><span class="mao-tk-toolkit__count"><?php echo esc_html(count(array_filter($modules, static function (array $module): bool { return $module['status'] === 'loaded'; })) . ' / ' . count($modules) . __(' 运行中', 'mao-tk-zibll-toolkit')); ?></span></div>
        <?php
        $groups = array('content' => array(__('内容与代码', 'mao-tk-zibll-toolkit'), array('article-ui-code', 'article-ui-link-preview')), 'organization' => array(__('内容组织', 'mao-tk-zibll-toolkit'), array('article-ui-tabs', 'article-ui-postsbox', 'article-ui-resources')), 'reading' => array(__('阅读体验', 'mao-tk-zibll-toolkit'), array('article-ui-reading')));
        foreach ($groups as $group_id => $group) :
            $group_modules = array_filter($modules, static function (array $module) use ($group): bool { return in_array($module['id'], $group[1], true); });
            if (!$group_modules) { continue; }
            Admin::disclosure_start('mao-tk-ui-' . $group_id, $group[0], count($group_modules) . __(' 项组件', 'mao-tk-zibll-toolkit'), false, 'article-ui-modules');
            foreach ($group_modules as $module) :
            $loaded = $module['status'] === 'loaded';
            $label = $loaded ? __('运行中', 'mao-tk-zibll-toolkit') : ($module['status'] === 'disabled' ? __('未启用', 'mao-tk-zibll-toolkit') : ($module['status'] === 'blocked' ? __('等待主题', 'mao-tk-zibll-toolkit') : __('加载失败', 'mao-tk-zibll-toolkit')));
        ?>
        <article class="mao-tk-toolkit__module"><div class="mao-tk-toolkit__module-copy"><h3><?php echo esc_html($module['name']); ?></h3><p><?php echo esc_html($module['description']); ?></p><p class="mao-tk-toolkit__module-note"><?php echo esc_html($loaded ? __('模块已在本次请求中加载。', 'mao-tk-zibll-toolkit') : __('正文及原生业务保持可用；启用后还需匹配文章包装与迁移条件。', 'mao-tk-zibll-toolkit')); ?></p></div><div class="mao-tk-toolkit__module-actions"><?php $switch_module = $module; $switch_valid = $valid; $switch_return_page = ArticleUI\AdminPage::SLUG; require MAO_TK_ZIBLL_TOOLKIT_DIR . 'inc/views/module-switch.php'; ?><span class="mao-tk-toolkit__badge mao-tk-toolkit__badge--<?php echo esc_attr($loaded ? 'success' : ($module['status'] === 'disabled' ? 'neutral' : 'warning')); ?>"><?php echo esc_html($label); ?></span></div></article>
        <?php endforeach; Admin::disclosure_end(); endforeach; ?>
    </section><section class="mao-tk-toolkit__panel"><?php Admin::disclosure_start('mao-tk-ui-usage', __('使用方式与迁移说明', 'mao-tk-zibll-toolkit'), __('组件包装、原生边界与旧文迁移', 'mao-tk-zibll-toolkit')); ?><div class="mao-tk-disclosure__copy"><p><?php esc_html_e('在 Gutenberg 的组区块“额外 CSS 类”填写', 'mao-tk-zibll-toolkit'); ?> <code>maotk-ui-kit</code><?php esc_html_e('，仅将需要增强的内容放入该组。', 'mao-tk-zibll-toolkit'); ?></p><p><?php esc_html_e('代码区块外层组填写', 'mao-tk-zibll-toolkit'); ?> <code>mtk-code-wrap</code><?php esc_html_e('；顶部 TAB 外层', 'mao-tk-zibll-toolkit'); ?> <code>mtk-native-tabs</code><?php esc_html_e('；文章短代码外层', 'mao-tk-zibll-toolkit'); ?> <code>mtk-native-postsbox</code><?php esc_html_e('。阅读与折叠在根组增加', 'mao-tk-zibll-toolkit'); ?> <code>mtk-article-reading</code><?php esc_html_e('。普通链接可使用', 'mao-tk-zibll-toolkit'); ?> <code>mtk-link-demo</code> <?php esc_html_e('段落范围。', 'mao-tk-zibll-toolkit'); ?></p><p><?php esc_html_e('推荐与外部工具入口在根组增加', 'mao-tk-zibll-toolkit'); ?> <code>mtk-legacy-resources</code><?php esc_html_e('，使用插件提供的推荐／工具结构；图标、边距与整卡链接沿用已确认样式。下方补充说明继续调用阅读折叠，实例 ID 必须唯一。', 'mao-tk-zibll-toolkit'); ?><a href="<?php echo esc_url(MAO_TK_ZIBLL_TOOLKIT_URL . 'article-ui/resources/README.md'); ?>" target="_blank" rel="noopener noreferrer"><?php esc_html_e('推荐与工具调用说明', 'mao-tk-zibll-toolkit'); ?></a></p><p><?php esc_html_e('插件只在显示时补充属性与 TAB 文字包装，不改写已存正文；不生成示例文章 ID，也不复制主题的代码工具或 TAB 事件。', 'mao-tk-zibll-toolkit'); ?></p><p><?php esc_html_e('已有 style/script 或旧预览浮层时先盘点、备份和逐组件去重。当前版本保守避让内嵌资源，不自动删除文章代码。', 'mao-tk-zibll-toolkit'); ?></p></div><?php Admin::disclosure_end(); ?></section></div>
    <aside class="mao-tk-toolkit__aside"><section class="mao-tk-toolkit__guide"><h2><?php esc_html_e('接入边界', 'mao-tk-zibll-toolkit'); ?></h2><p><?php esc_html_e('原生下载、付费、会员、商品、媒体和目录保持原样。阅读与折叠仅在明确标记的正文中启用；商品宽度不在本模块中接管。', 'mao-tk-zibll-toolkit'); ?></p><p><?php esc_html_e('本地定稿归档已校验；当前真实 WordPress、主题版本、编辑器保存及局部刷新仍需在测试站验收。', 'mao-tk-zibll-toolkit'); ?></p><p><a href="<?php echo esc_url(MAO_TK_ZIBLL_TOOLKIT_URL . 'article-ui/README.md'); ?>" target="_blank" rel="noopener noreferrer"><?php esc_html_e('插入示例、迁移与回退说明', 'mao-tk-zibll-toolkit'); ?></a></p><p><a href="<?php echo esc_url(admin_url('admin.php?page=' . ArticleNote\AdminPage::SLUG)); ?>"><?php esc_html_e('正文提示框设置与预览', 'mao-tk-zibll-toolkit'); ?></a><?php esc_html_e('：独立的原 maotk/note 区块，无需以上组件的外层包装。', 'mao-tk-zibll-toolkit'); ?></p></section></aside></div>
